initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing a Context Source Registration Subscription (CSRS1)
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Retrieve Context Source Registration Subscription with Response Status Code set to 200     and
        Retrieve Context Source Registration Subscription with Response Body containing the same content defined in file 'csourceSubscriptions/expectations/subscriptions-040-01-expectation.json' with subscription id '${subscription_id}'
}
